const text = v => !v ? "" : (v.title||v.rich_text||[]).map(t=>t.plain_text).join("");
let war = false;
for (const it of $('Notion System Flags').all()) {
  const p = it.json.properties || {};
  let title = "";
  for (const k in p) if (p[k].type === "title") title = text(p[k]);
  if (/war/i.test(title)) war = p["Value"]?.checkbox === true;
}
const SEV = ["FIRE","IMPORTANT","ROUTINE","AWARENESS"];
const OWN = ["Conductor","Estimator","Support","Marketer","Shield/Ops","Researcher"];
let r;
try {
  let raw = ($json.content?.[0]?.text || "").trim().replace(/^```(?:json)?/i,"").replace(/```$/,"").trim();
  const m = raw.match(/\{[\s\S]*\}/);
  const o = JSON.parse(m ? m[0] : raw);
  if (!SEV.includes(o.severity) || !OWN.includes(o.owner)) throw new Error("bad enum");
  r = { severity:o.severity, owner:o.owner, reason:String(o.reason||""), needs_human:o.needs_human===true, summary:String(o.summary||"") };
} catch (e) {
  r = { severity:"IMPORTANT", owner:"Conductor", reason:"Router output could not be parsed; defaulting to human review.", needs_human:true, summary:"" };
}
r.queued_for_brief = false;
if (war && r.severity !== "FIRE") { r.needs_human = false; r.queued_for_brief = true; }
r.war_mode = war;
return [{ json: { routing: r } }];
